export function createOfflineQueue({
  storage,
  send,
  key = "queue:v1",
  maxAttempts = 5,
}) {
  let items = [];

  try {
    const stored = storage.getItem(key);

    if (stored !== null) {
      const parsed = JSON.parse(stored);

      if (Array.isArray(parsed)) {
        items = parsed;
      }
    }
  } catch {
    items = [];
  }

  let inFlight = null;
  let runningFlush = null;

  function persist() {
    storage.setItem(key, JSON.stringify(items));
  }

  function enqueue(action) {
    const id = action.id;

    if (items.some((item) => item.id === id)) {
      return;
    }

    const dedupeKey = action.dedupeKey;

    if (dedupeKey !== undefined) {
      const existingIndex = items.findIndex(
        (item) =>
          item !== inFlight && item.dedupeKey === dedupeKey,
      );

      if (existingIndex !== -1) {
        const existing = items[existingIndex];
        const type = action.type;
        const payload = action.payload;

        existing.type = type;
        existing.payload = payload;
        existing.attempts = 0;
        persist();
        return;
      }
    }

    items.push({
      id,
      type: action.type,
      payload: action.payload,
      dedupeKey,
      attempts: 0,
    });

    persist();
  }

  function size() {
    return items.length;
  }

  function peek() {
    return items.map((item) => ({
      id: item.id,
      type: item.type,
      payload: item.payload,
      dedupeKey: item.dedupeKey,
      attempts: item.attempts,
    }));
  }

  async function runFlush() {
    const sent = [];
    const failed = [];

    try {
      while (items.length > 0) {
        const item = items[0];
        inFlight = item;

        let response;
        let rejected = false;

        try {
          response = await send({
            id: item.id,
            type: item.type,
            payload: item.payload,
          });
        } catch {
          rejected = true;
        }

        let outcome = "retryable";

        if (!rejected) {
          try {
            const ok =
              response !== null && response !== undefined
                ? response.ok
                : undefined;

            if (ok === true) {
              outcome = "success";
            } else if (
              ok === false &&
              response.retryable === false
            ) {
              outcome = "permanent";
            }
          } catch {
            outcome = "retryable";
          }
        }

        inFlight = null;

        if (outcome === "success") {
          items.shift();
          persist();
          sent.push(item.id);
          continue;
        }

        if (outcome === "permanent") {
          items.shift();
          persist();
          failed.push({
            id: item.id,
            reason: "rejected",
          });
          continue;
        }

        item.attempts += 1;
        persist();

        if (item.attempts >= maxAttempts) {
          items.shift();
          persist();
          failed.push({
            id: item.id,
            reason: "max-attempts",
          });
        }

        return {
          sent,
          failed,
          remaining: items.length,
        };
      }

      return {
        sent,
        failed,
        remaining: 0,
      };
    } finally {
      inFlight = null;
    }
  }

  function flush() {
    if (runningFlush !== null) {
      return runningFlush;
    }

    let resolveFlush;
    let rejectFlush;

    const promise = new Promise((resolve, reject) => {
      resolveFlush = resolve;
      rejectFlush = reject;
    });

    runningFlush = promise;

    runFlush().then(
      (result) => {
        if (runningFlush === promise) {
          runningFlush = null;
        }
        resolveFlush(result);
      },
      (error) => {
        if (runningFlush === promise) {
          runningFlush = null;
        }
        rejectFlush(error);
      },
    );

    return promise;
  }

  return {
    enqueue,
    flush,
    size,
    peek,
  };
}
